#!/usr/lib/python3
# -*- coding: utf-8 -*-

"""
    Module containing utility class helping with parsing/creating parameters
    in urls.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import re


class CUrlParser:
    """
        Creates proper urls along with parameters for Velocity services.
        Use case::

            velocity_url = self.CUrlParser(url, url_parameters)
            print(velocity_url)

        Class supports string adding::

            # url = api/inventory/v5/devices
            velocity_url = self.CUrlParser(url, url_parameters)
            print('/velocity/' + velocity_url)  # prints /velocity/api/inventory/v5/devices
            print(velocity_url + '/velocity/')  # prints /velocity/api/inventory/v5/devices

        Arguments:
            url (str): Url to Velocity's service.
            allowed_filter_keys (list): List with all accepted filter's keys.
            pageable (bool): Is Velocity response's pageable (`pagination
                <https://10.34.180.112/velocity/api/doc#pagination/>`_).
            sortable (bool): Is Velocity response's sortable (`sorting
                <https://10.34.180.112/velocity/api/doc#sorting/>`_).
            filterable (bool): Is Velocity response's filterable (`filtering
                <https://10.34.180.112/velocity/api/doc#filtering/>`_).
    """

    def __init__(
            self, url, kwargs={}, allowed_filter_keys=[], pageable=False,
            sortable=False, filterable=False
    ):
        self._pageable = pageable
        self._sortable = sortable
        self._filterable = filterable
        self._pagable_params = ['limit', 'offset']
        self._sortable_params = ['sortBy', 'sortOrder']
        self._filterable_params = ['filter']
        self._allowed_filter_keys = allowed_filter_keys
        if not kwargs:
            self.url = url
        else:
            params = self._parse_parameters(kwargs)
            if params:
                self.url = "{}?{}".format(url, params)
            else:
                self.url = url

    def __str__(self):
        return self.url

    def __add__(self, string):
        return '{}{}'.format(string, self.url)

    def __radd__(self, string):
        return '{}{}'.format(string, self.url)

    def _remove_params(self, params):
        """
            Method removes unsupported or wrong params from params list.

            Arguments:
                params (list): list of params to parse.

            Returns:
                (list): Updated params list.
        """

        params_to_remove = []
        if not self._pageable:
            params_to_remove += self._pagable_params

        if not self._sortable:
            params_to_remove += self._sortable_params
        else:
            try:
                if params['sortOrder'] != 'desc':  # api reads only desc,
                    del params['sortOrder']  # everything else is 'ascending'
            except KeyError:
                pass

        if not self._filterable:
            params_to_remove += self._filterable_params

        for param_key in params_to_remove:
            if param_key in params.keys():
                del params[param_key]
        return params

    def _parse_filters(self, param_filter):
        """
            Method parses filter field and checks if it's correct.

            Arguments:
                param_filter (str): Line with all filters.

            Returns:
                str: Correct filter line.
        """

        allowed_filters_list = []
        line = re.split(r'[&\n]', param_filter)
        for elem in line:
            if elem.split(':')[0] in self._allowed_filter_keys \
                    or 'any' in self._allowed_filter_keys:
                allowed_filters_list.append(elem)
        param_filter = '&filter='.join(allowed_filters_list)
        return param_filter

    def _parse_parameters(self, params):
        """
            Method parses dict of parameters and returns correct ones as string
            appendable to url.

            Arguments:
                params (dict): List of params.

            Returns:
                str: Line of parameters that can be added to url.
        """

        parameters_list = []
        params = self._remove_params(params)
        try:
            params['filter'] = self._parse_filters(params['filter'])
        except KeyError:
            pass
        for key, value in params.items():
            if value is not None:
                parameters_list.append("{}={}".format(key, value))
        return '&'.join(parameters_list)
